function id(selector){return document.getElementById(selector);}
function qs(selector){return document.querySelector(selector);}
function qsa(selector){return Array.from(document.querySelectorAll(selector));}
function showToast(message,type='info'){const existing=qs('.toast');if(existing)existing.remove();const toast=document.createElement('div');toast.className=`toast toast-${type}`;toast.innerHTML=`
        <i class="fas ${type === 'success' ? 'fa-check-circle' :
                        type === 'error'   ? 'fa-times-circle' :
                                            'fa-info-circle'}"></i>
        <span>${message}</span>
    `;Object.assign(toast.style,{position:'fixed',bottom:'2rem',right:'2rem',background:type==='success'?'rgba(16,185,129,0.95)':type==='error'?'rgba(239,68,68,0.95)':'rgba(0,212,255,0.95)',color:type==='info'?'#020408':'white',padding:'0.85rem 1.4rem',borderRadius:'10px',display:'flex',alignItems:'center',gap:'0.6rem',fontSize:'0.9rem',fontWeight:'600',fontFamily:'Inter, sans-serif',zIndex:'9999',boxShadow:'0 8px 30px rgba(0,0,0,0.4)',transform:'translateY(20px)',opacity:'0',transition:'all 0.3s ease',});document.body.appendChild(toast);requestAnimationFrame(()=>{toast.style.transform='translateY(0)';toast.style.opacity='1';});setTimeout(()=>{toast.style.transform='translateY(20px)';toast.style.opacity='0';setTimeout(()=>toast.remove(),300);},3000);}
function initDate(){const dateEl=id('current-date');if(!dateEl)return;const now=new Date();const options={weekday:'long',year:'numeric',month:'long',day:'numeric'};dateEl.textContent=now.toLocaleDateString('en-US',options);}
function initMobileNav(){const hamburger=id('hamburger');const nav=qs('.main-nav');if(!hamburger||!nav)return;hamburger.addEventListener('click',function(){const isOpen=nav.classList.toggle('nav-open');hamburger.classList.toggle('open',isOpen);hamburger.setAttribute('aria-expanded',isOpen);});document.addEventListener('click',function(e){if(!hamburger.contains(e.target)&&!nav.contains(e.target)){nav.classList.remove('nav-open');hamburger.classList.remove('open');}});}
function initTicker(){const tickerItems=qs('.ticker-items');if(!tickerItems)return;const originalHTML=tickerItems.innerHTML;tickerItems.innerHTML=originalHTML+originalHTML;const tickerWrap=qs('.ticker-wrap');if(tickerWrap){tickerWrap.addEventListener('mouseenter',()=>{tickerItems.style.animationPlayState='paused';});tickerWrap.addEventListener('mouseleave',()=>{tickerItems.style.animationPlayState='running';});}}
function initSearch(){var searchInput=id('search-input');if(!searchInput)return;document.addEventListener('keydown',function(e){var tag=document.activeElement.tagName.toLowerCase();if(tag==='input'||tag==='textarea')return;if(e.key==='/'){e.preventDefault();searchInput.focus();searchInput.select();}});searchInput.addEventListener('keydown',function(e){if(e.key==='Escape'){this.value='';this.blur();}});}
function initCategoryFilter(){var filterBtns=qsa('.filter-btn');if(!filterBtns.length)return;filterBtns.forEach(function(btn){btn.addEventListener('click',function(){filterBtns.forEach(function(b){b.classList.remove('active');});this.classList.add('active');currentCategory=this.getAttribute('data-category');var searchInput=id('search-input');if(searchInput&&searchInput.value.trim()){applyFilters();return;}
var cards=qsa('.article-card');var visible=0;var noResult=id('no-results');cards.forEach(function(card){var cardCat=card.getAttribute('data-category');var matches=currentCategory==='all'||cardCat===currentCategory;if(matches){card.style.display='';visible++;}else{card.style.display='none';}});if(noResult){noResult.style.display=visible===0?'block':'none';}
var statEl=id('stat-articles');if(statEl)statEl.textContent=visible;});});}
function applyFilters(){const cards=qsa('.article-card');const noResult=id('no-results');let visible=0;cards.forEach(function(card){const cardCategory=card.getAttribute('data-category');const cardText=card.textContent.toLowerCase();const matchesCategory=currentCategory==='all'||cardCategory===currentCategory;const matchesSearch=currentSearch===''||cardText.includes(currentSearch);if(matchesCategory&&matchesSearch){card.style.display='';card.style.animation='none';void card.offsetWidth;card.style.animation='';visible++;}else{card.style.display='none';}});if(noResult){noResult.style.display=visible===0?'block':'none';}
const statArticles=id('stat-articles');if(statArticles){statArticles.textContent=visible;}}
function initBookmarks(){const grid=id('articles-grid');if(!grid)return;grid.addEventListener('click',function(e){const btn=e.target.closest('.action-btn[title="Bookmark"]');if(!btn)return;const icon=btn.querySelector('i');if(!icon)return;const isBookmarked=icon.classList.contains('fa-solid');if(isBookmarked){icon.classList.replace('fa-solid','fa-regular');btn.style.color='';showToast('Bookmark removed','info');}else{icon.classList.replace('fa-regular','fa-solid');btn.style.color='#00d4ff';showToast('Article bookmarked! 🔖','success');}});}
function initShare(){const grid=id('articles-grid');if(!grid)return;grid.addEventListener('click',function(e){const btn=e.target.closest('.action-btn[title="Share"]');if(!btn)return;const card=btn.closest('.article-card');const link=card?card.querySelector('.card-read-more'):null;const url=link?window.location.origin+link.getAttribute('href'):window.location.href;if(navigator.clipboard){navigator.clipboard.writeText(url).then(()=>{showToast('Link copied to clipboard! 📋','success');});}else{showToast('Copy this link: '+url,'info');}});}
function initNewsletterForms(){const forms=[{input:document.querySelector('.newsletter-form input'),button:document.querySelector('.newsletter-form button'),},{input:document.querySelector('.footer-newsletter input'),button:document.querySelector('.footer-newsletter button'),}];forms.forEach(function({input,button}){if(!button||!input)return;button.addEventListener('click',async function(){const email=input.value.trim();if(!email){showToast('Please enter your email address','error');input.focus();return;}
if(!email.includes('@')||!email.includes('.')){showToast('Please enter a valid email address','error');input.focus();return;}
button.disabled=true;button.textContent='Subscribing...';try{const response=await fetch('/api/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email}),});const data=await response.json();if(data.success){showToast(data.message,'success');input.value='';}else{showToast(data.message,'error');}}catch(err){showToast('Connection error. Please try again.','error');}finally{button.disabled=false;button.innerHTML='Subscribe <i class="fas fa-paper-plane"></i>';}});input.addEventListener('keydown',function(e){if(e.key==='Enter')button.click();});});}
function initScrollEffects(){const header=qs('.main-header');window.addEventListener('scroll',function(){if(!header)return;if(window.scrollY>10){header.style.boxShadow='0 4px 30px rgba(0, 0, 0, 0.5)';}else{header.style.boxShadow='none';}});const backBtn=document.createElement('button');backBtn.id='back-to-top';backBtn.innerHTML='<i class="fas fa-arrow-up"></i>';backBtn.title='Back to top';Object.assign(backBtn.style,{position:'fixed',bottom:'2rem',left:'2rem',width:'44px',height:'44px',background:'rgba(0, 212, 255, 0.15)',border:'1px solid rgba(0, 212, 255, 0.3)',borderRadius:'50%',color:'#00d4ff',fontSize:'1rem',cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center',opacity:'0',transform:'translateY(20px)',transition:'all 0.3s ease',zIndex:'999',fontFamily:'inherit',});document.body.appendChild(backBtn);window.addEventListener('scroll',function(){if(window.scrollY>400){backBtn.style.opacity='1';backBtn.style.transform='translateY(0)';}else{backBtn.style.opacity='0';backBtn.style.transform='translateY(20px)';}});backBtn.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});});backBtn.addEventListener('mouseenter',function(){this.style.background='rgba(0, 212, 255, 0.3)';});backBtn.addEventListener('mouseleave',function(){this.style.background='rgba(0, 212, 255, 0.15)';});}
function initThreatMeter(){const fill=qs('.threat-fill');if(!fill)return;const targetWidth=fill.style.width;fill.style.width='0%';setTimeout(function(){fill.style.transition='width 1.5s ease';fill.style.width=targetWidth;},500);}
function animateCounter(element,target,duration=1500){let start=null;const initial=0;function step(timestamp){if(!start)start=timestamp;const progress=Math.min((timestamp-start)/duration,1);const eased=1-Math.pow(1-progress,3);const current=Math.round(initial+(target-initial)*eased);element.textContent=current;if(progress<1){requestAnimationFrame(step);}}
requestAnimationFrame(step);}
function initStatsCounters(){const statNumbers=qsa('.stat-number');statNumbers.forEach(function(el){const target=parseInt(el.textContent,10);if(!isNaN(target)&&target>0){animateCounter(el,target,1500);}});}
function initScrollAnimations(){const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}});},{threshold:0.1,rootMargin:'0px 0px -50px 0px'});qsa('.widget').forEach(el=>observer.observe(el));qsa('.category-card').forEach(el=>observer.observe(el));qsa('.feature-card').forEach(el=>observer.observe(el));}
function initKeyboardShortcuts(){document.addEventListener('keydown',function(e){const tag=document.activeElement.tagName.toLowerCase();if(tag==='input'||tag==='textarea')return;switch(e.key){case'/':e.preventDefault();const searchInput=id('search-input');if(searchInput){searchInput.focus();searchInput.select();}
break;case'Escape':const si=id('search-input');if(si&&si.value){si.value='';currentSearch='';const notice=id('search-notice');if(notice)notice.style.display='none';applyFilters();}
break;case'1':clickFilterBtn('all');break;case'2':clickFilterBtn('Malware');break;case'3':clickFilterBtn('Data Breaches');break;case'4':clickFilterBtn('Vulnerabilities');break;}});}
function clickFilterBtn(category){const btn=qs(`.filter-btn[data-category="${category}"]`);if(btn)btn.click();}
function initActiveNav(){const currentPath=window.location.pathname;const navLinks=qsa('.nav-link');navLinks.forEach(function(link){const href=link.getAttribute('href');if(href===currentPath){link.classList.add('active');}else if(currentPath!=='/'&&href!=='/'&&currentPath.startsWith(href)){link.classList.add('active');}});}
function injectAnimationCSS(){const style=document.createElement('style');style.textContent=`
        /* Elements start invisible and slide up */
        .widget,
        .category-card,
        .feature-card {
            opacity: 0;
            transform: translateY(24px);
            transition: opacity 0.5s ease, transform 0.5s ease;
        }

        /* When JS adds this class, they become visible */
        .widget.is-visible,
        .category-card.is-visible,
        .feature-card.is-visible {
            opacity: 1;
            transform: translateY(0);
        }

        /* Stagger category cards */
        .category-card:nth-child(1) { transition-delay: 0.05s; }
        .category-card:nth-child(2) { transition-delay: 0.10s; }
        .category-card:nth-child(3) { transition-delay: 0.15s; }
        .category-card:nth-child(4) { transition-delay: 0.20s; }
        .category-card:nth-child(5) { transition-delay: 0.25s; }
        .category-card:nth-child(6) { transition-delay: 0.30s; }

        /* Hamburger open state — turns into X */
        .hamburger.open span:nth-child(1) {
            transform: translateY(7px) rotate(45deg);
        }
        .hamburger.open span:nth-child(2) {
            opacity: 0;
            transform: scaleX(0);
        }
        .hamburger.open span:nth-child(3) {
            transform: translateY(-7px) rotate(-45deg);
        }

        /* Smooth hamburger span transitions */
        .hamburger span {
            transition: transform 0.3s ease, opacity 0.3s ease;
        }
    `;document.head.appendChild(style);}
function initLiveCounter(){const liveCount=qs('.live-count');if(!liveCount)return;setInterval(function(){const current=parseInt(liveCount.textContent,10);const change=Math.floor(Math.random()*4)-1;const next=Math.max(8,Math.min(20,current+change));if(next!==current){liveCount.style.transition='color 0.3s ease';liveCount.style.color=next>current?'#ef4444':'#10b981';setTimeout(()=>{liveCount.textContent=next;liveCount.style.color='';},300);}},8000);}
function initReadingProgress(){if(!qs('.article-body'))return;const bar=document.createElement('div');bar.id='reading-progress';Object.assign(bar.style,{position:'fixed',top:'0',left:'0',height:'3px',width:'0%',background:'linear-gradient(90deg, #00d4ff, #7c3aed)',zIndex:'9999',transition:'width 0.1s linear',});document.body.appendChild(bar);window.addEventListener('scroll',function(){const scrollTop=window.scrollY;const docHeight=document.documentElement.scrollHeight;const windowHeight=window.innerHeight;const scrollable=docHeight-windowHeight;if(scrollable>0){const progress=(scrollTop/scrollable)*100;bar.style.width=progress+'%';}});}
function initAlerts(){var btn=document.getElementById('alerts-btn');var panel=document.getElementById('alerts-panel');var badge=document.getElementById('alerts-count');if(!btn||!panel)return;btn.addEventListener('click',function(e){e.stopPropagation();var isOpen=panel.classList.toggle('open');if(isOpen&&badge){badge.style.display='none';}});document.addEventListener('click',function(e){var dropdown=document.getElementById('alerts-dropdown');if(dropdown&&!dropdown.contains(e.target)){panel.classList.remove('open');}});document.addEventListener('keydown',function(e){if(e.key==='Escape'){panel.classList.remove('open');}});if(badge){var items=document.querySelectorAll('.alert-item');badge.textContent=items.length;}}
document.addEventListener('DOMContentLoaded',function(){injectAnimationCSS();initDate();initMobileNav();initTicker();initActiveNav();initSearch();initCategoryFilter();initBookmarks();initShare();initNewsletterForms();initScrollEffects();initThreatMeter();initStatsCounters();initScrollAnimations();initLiveCounter();initReadingProgress();initKeyboardShortcuts();initThemeToggle();initEasterEgg();initAlerts();initTypingEffect();initParticles();initTerminal();initScrollReveal();initAboutPage();setTimeout(function(){showToast('💡 Press "/" to quickly search articles','info');},2000);console.log('%c CyberNews Loaded ✓ ','background:#00d4ff; color:#020408; font-weight:bold; padding:4px 8px; border-radius:4px;');});function initThemeToggle(){var toggle=document.getElementById('theme-toggle');var icon=document.getElementById('theme-icon');if(!toggle||!icon)return;var saved=localStorage.getItem('cybernews-theme');if(saved==='light'){document.body.classList.add('light-mode');icon.className='fas fa-moon';}
toggle.addEventListener('click',function(){var isLight=document.body.classList.toggle('light-mode');if(isLight){icon.className='fas fa-moon';localStorage.setItem('cybernews-theme','light');showToast('Light mode activated ☀️','info');}else{icon.className='fas fa-sun';localStorage.setItem('cybernews-theme','dark');showToast('Dark mode activated 🌙','info');}});}
function initEasterEgg(){var sequence=['ArrowUp','ArrowUp','ArrowDown','ArrowDown','ArrowLeft','ArrowRight','ArrowLeft','ArrowRight','b','a'];var position=0;document.addEventListener('keydown',function(e){var tag=document.activeElement.tagName.toLowerCase();if(tag==='input'||tag==='textarea')return;if(e.key===sequence[position]){position++;if(position===sequence.length){position=0;activateEasterEgg();}}else{position=0;}});}
function activateEasterEgg(){showToast('🎮 Konami Code activated! Welcome, hacker!','success');var cards=document.querySelectorAll('.article-card');cards.forEach(function(card,i){setTimeout(function(){card.style.border='2px solid';card.style.borderImage='linear-gradient(135deg, #ef4444, #f59e0b, #10b981, #3b82f6, #8b5cf6) 1';},i*150);});var overlay=document.createElement('div');overlay.style.cssText=['position: fixed','inset: 0','z-index: 9998','pointer-events: none','background: rgba(0, 255, 0, 0.05)','transition: opacity 3s ease',].join(';');document.body.appendChild(overlay);for(var i=0;i<50;i++){createMatrixChar(i);}
setTimeout(function(){overlay.style.opacity='0';setTimeout(function(){overlay.remove();},3000);},1000);setTimeout(function(){cards.forEach(function(card){card.style.border='';card.style.borderImage='';});},5000);}
function createMatrixChar(index){var chars='01アイウエオカキクケコサシスセソ';var el=document.createElement('div');var x=Math.random()*100;el.textContent=chars[Math.floor(Math.random()*chars.length)];el.style.cssText=['position: fixed','top: -20px','left: '+x+'%','color: rgba(0, 255, 0, 0.6)','font-family: monospace','font-size: '+(12+Math.random()*14)+'px','z-index: 9999','pointer-events: none','text-shadow: 0 0 10px rgba(0, 255, 0, 0.8)','animation: matrixFall '+(2+Math.random()*3)+'s linear forwards','animation-delay: '+(index*0.1)+'s',].join(';');document.body.appendChild(el);setTimeout(function(){el.remove();},6000);}
function initTypingEffect(){var summary=document.querySelector('.hero-summary');if(!summary)return;var fullText=summary.textContent.trim();summary.textContent='';summary.style.borderRight='2px solid var(--primary)';var i=0;var speed=20;function type(){if(i<fullText.length){summary.textContent+=fullText.charAt(i);i++;setTimeout(type,speed);}else{setTimeout(function(){summary.style.borderRight='none';},1500);}}
setTimeout(type,800);}
function initParticles(){if(!document.querySelector('.hero'))return;var canvas=document.createElement('canvas');canvas.id='particle-canvas';canvas.style.cssText=['position: fixed','top: 0','left: 0','width: 100%','height: 100%','z-index: -1','pointer-events: none','opacity: 0.4',].join(';');document.body.appendChild(canvas);var ctx=canvas.getContext('2d');var particles=[];var particleCount=40;var connectDistance=150;var mouseX=0;var mouseY=0;function resize(){canvas.width=window.innerWidth;canvas.height=window.innerHeight;}
resize();window.addEventListener('resize',resize);document.addEventListener('mousemove',function(e){mouseX=e.clientX;mouseY=e.clientY;});for(var i=0;i<particleCount;i++){particles.push({x:Math.random()*canvas.width,y:Math.random()*canvas.height,vx:(Math.random()-0.5)*0.5,vy:(Math.random()-0.5)*0.5,size:Math.random()*2+1,color:Math.random()>0.5?'0, 212, 255':'124, 58, 237',});}
function animate(){ctx.clearRect(0,0,canvas.width,canvas.height);for(var i=0;i<particles.length;i++){var p=particles[i];p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>canvas.width)p.vx*=-1;if(p.y<0||p.y>canvas.height)p.vy*=-1;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fillStyle='rgba('+p.color+', 0.6)';ctx.fill();for(var j=i+1;j<particles.length;j++){var p2=particles[j];var dx=p.x-p2.x;var dy=p.y-p2.y;var dist=Math.sqrt(dx*dx+dy*dy);if(dist<connectDistance){var opacity=(1-dist/connectDistance)*0.3;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p2.x,p2.y);ctx.strokeStyle='rgba(0, 212, 255, '+opacity+')';ctx.lineWidth=0.5;ctx.stroke();}}
var mx=p.x-mouseX;var my=p.y-mouseY;var mouseDist=Math.sqrt(mx*mx+my*my);if(mouseDist<200){var mOpacity=(1-mouseDist/200)*0.5;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(mouseX,mouseY);ctx.strokeStyle='rgba(0, 255, 136, '+mOpacity+')';ctx.lineWidth=0.8;ctx.stroke();}}
requestAnimationFrame(animate);}
animate();}
function initTerminal(){var terminal=document.getElementById('live-terminal');if(!terminal)return;var maxLines=20;var commandIndex=0;var staticCommands=[{type:'cmd',text:'nmap -sS --top-ports 100 target'},{type:'cmd',text:'tail -f /var/log/auth.log'},{type:'cmd',text:'suricata -c /etc/suricata.yaml -i eth0'},{type:'cmd',text:'fail2ban-client status sshd'},{type:'cmd',text:'openssl s_client -connect server:443'},{type:'cmd',text:'curl -I https://cybernews/health'},{type:'cmd',text:'grep BLOCKED /var/log/security.log'},{type:'cmd',text:'systemctl status nginx gunicorn'},];function addLine(type,text){var line=document.createElement('div');line.className='terminal-line';if(type==='cmd'){line.innerHTML='<span class="t-prompt">sec@cybernews ~$</span> <span class="t-cmd">'+text+'</span>';}else{line.innerHTML='<span class="t-'+type+'">'+text+'</span>';}
terminal.appendChild(line);var lines=terminal.querySelectorAll('.terminal-line');if(lines.length>maxLines){lines[0].remove();}
terminal.scrollTop=terminal.scrollHeight;}
function fetchRealData(){fetch('/api/live-feed').then(function(response){return response.json();}).then(function(data){if(data.events&&data.events.length>0){var cmd=staticCommands[commandIndex%staticCommands.length];addLine('cmd',cmd.text);commandIndex++;var eventsToShow=data.events.slice(0,3);var delay=800;eventsToShow.forEach(function(event,i){setTimeout(function(){addLine(event.type,'['+event.time+'] '+event.text);},delay*(i+1));});}}).catch(function(){addLine('warn','Connection timeout. Retrying...');});}
addLine('cmd','cybernews --security-monitor --start');addLine('success','Security monitor initialized');addLine('info','Connecting to live feed...');setTimeout(fetchRealData,3000);setInterval(fetchRealData,15000);}
function initScrollReveal(){var selectors=['.stat-item','.article-card','.widget','.category-card','.feature-card','.about-text h2','.tech-badge',];selectors.forEach(function(selector){var elements=document.querySelectorAll(selector);elements.forEach(function(el){el.classList.add('reveal-on-scroll');});});var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target);}});},{threshold:0.1,rootMargin:'0px 0px -30px 0px',});document.querySelectorAll('.reveal-on-scroll').forEach(function(el){observer.observe(el);});}
function initAboutPage(){if(!document.querySelector('.about-stats-row'))return;var statNumbers=document.querySelectorAll('.about-stat-number');var counterObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting)return;var el=entry.target;var target=parseInt(el.getAttribute('data-target'),10);var start=0;var duration=2000;var startTime=null;function countUp(timestamp){if(!startTime)startTime=timestamp;var progress=Math.min((timestamp-startTime)/duration,1);var eased=1-Math.pow(1-progress,3);el.textContent=Math.round(start+(target-start)*eased);if(progress<1){requestAnimationFrame(countUp);}}
requestAnimationFrame(countUp);counterObserver.unobserve(el);});},{threshold:0.5});statNumbers.forEach(function(el){counterObserver.observe(el);});var skillFills=document.querySelectorAll('.skill-fill');var skillObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting)return;var bar=entry.target;var width=bar.getAttribute('data-width');setTimeout(function(){bar.style.width=width+'%';},200);skillObserver.unobserve(bar);});},{threshold:0.3});skillFills.forEach(function(bar){skillObserver.observe(bar);});var timelineItems=document.querySelectorAll('.timeline-item');var timelineObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting)return;entry.target.style.opacity='1';entry.target.style.transform='translateX(0)';timelineObserver.unobserve(entry.target);});},{threshold:0.2});timelineItems.forEach(function(item,index){item.style.opacity='0';item.style.transform='translateX(-20px)';item.style.transition='opacity 0.5s ease '+(index*0.15)+'s, transform 0.5s ease '+(index*0.15)+'s';timelineObserver.observe(item);});}